import{_ as i,o as a,c as e,a2 as n}from"./chunks/framework.BqNd1sPY.js";const w=JSON.parse('{"title":"D02：文字如何变成数字","description":"","frontmatter":{},"headers":[],"relativePath":"01-14天理论课/D02-文字如何变成数字.md","filePath":"01-14天理论课/D02-文字如何变成数字.md"}'),r={name:"01-14天理论课/D02-文字如何变成数字.md"};function o(d,t,k,s,m,l){return a(),e("div",null,[...t[0]||(t[0]=[n(`<h1 id="d02-文字如何变成数字" tabindex="-1">D02：文字如何变成数字 <a class="header-anchor" href="#d02-文字如何变成数字" aria-label="Permalink to &quot;D02：文字如何变成数字&quot;">​</a></h1><h2 id="今日目标" tabindex="-1">今日目标 <a class="header-anchor" href="#今日目标" aria-label="Permalink to &quot;今日目标&quot;">​</a></h2><p>理解 <a href="/LLMTrain/05-速查表/术语速查#term-token" class="wiki-term" data-wiki-title="token" data-wiki-summary="文本经过分词规则得到的离散单元，随后会映射成整数 ID。" data-wiki-misconception="token 必然等于一个字或一个完整单词。">token</a>、<a href="/LLMTrain/05-速查表/术语速查#term-token" class="wiki-term" data-wiki-title="token" data-wiki-summary="文本经过分词规则得到的离散单元，随后会映射成整数 ID。" data-wiki-misconception="token 必然等于一个字或一个完整单词。">token</a> ID、<a href="/LLMTrain/05-速查表/术语速查#term-vocab" class="wiki-term" data-wiki-title="vocab" data-wiki-summary="tokenizer 可以表示的 token 集合；输出层通常也对这组 token 给出分数。" data-wiki-misconception="词表包含了模型掌握的全部知识。">词表</a>、<a href="/LLMTrain/05-速查表/术语速查#term-embedding" class="wiki-term" data-wiki-title="embedding" data-wiki-summary="把离散 ID 映射为连续向量的可训练表示。" data-wiki-misconception="embedding 是人工指定的固定语义坐标。">Embedding</a> 和位置信息的区别。</p><h2 id="tokenizer-像可逆的切块规则" tabindex="-1">Tokenizer 像可逆的切块规则 <a class="header-anchor" href="#tokenizer-像可逆的切块规则" aria-label="Permalink to &quot;Tokenizer 像可逆的切块规则&quot;">​</a></h2><p>假设一个玩具<a href="/LLMTrain/05-速查表/术语速查#term-vocab" class="wiki-term" data-wiki-title="vocab" data-wiki-summary="tokenizer 可以表示的 token 集合；输出层通常也对这组 token 给出分数。" data-wiki-misconception="词表包含了模型掌握的全部知识。">词表</a>是：</p><table tabindex="0"><thead><tr><th><a href="/LLMTrain/05-速查表/术语速查#term-token" class="wiki-term" data-wiki-title="token" data-wiki-summary="文本经过分词规则得到的离散单元，随后会映射成整数 ID。" data-wiki-misconception="token 必然等于一个字或一个完整单词。">token</a></th><th style="text-align:right;">ID</th></tr></thead><tbody><tr><td>我</td><td style="text-align:right;">0</td></tr><tr><td>爱</td><td style="text-align:right;">1</td></tr><tr><td>学</td><td style="text-align:right;">2</td></tr><tr><td>习</td><td style="text-align:right;">3</td></tr><tr><td>学习</td><td style="text-align:right;">4</td></tr><tr><td><code>&lt;eos&gt;</code></td><td style="text-align:right;">5</td></tr></tbody></table><p>“我爱学习”可能编码成 <code>[0, 1, 4, 5]</code>。这里的 <code>4</code> 只是编号，不代表“学习”的大小或价值。</p><p>真实 <a href="/LLMTrain/05-速查表/术语速查#term-tokenizer" class="wiki-term" data-wiki-title="tokenizer" data-wiki-summary="负责把文本切成 token，并在 token 与整数 ID 之间转换的规则和词表。" data-wiki-misconception="tokenizer 是模型自己临时决定的切词方式。">tokenizer</a> 可能以字节、字符或子词为基础。一个汉字不保证等于一个 <a href="/LLMTrain/05-速查表/术语速查#term-token" class="wiki-term" data-wiki-title="token" data-wiki-summary="文本经过分词规则得到的离散单元，随后会映射成整数 ID。" data-wiki-misconception="token 必然等于一个字或一个完整单词。">token</a>，一个英文单词也可能被拆成多个 <a href="/LLMTrain/05-速查表/术语速查#term-token" class="wiki-term" data-wiki-title="token" data-wiki-summary="文本经过分词规则得到的离散单元，随后会映射成整数 ID。" data-wiki-misconception="token 必然等于一个字或一个完整单词。">token</a>。<a href="/LLMTrain/05-速查表/术语速查#term-context" class="wiki-term" data-wiki-title="context" data-wiki-summary="模型本次计算能够看到的 token 序列。" data-wiki-misconception="放进上下文的信息已经永久写入模型参数。">上下文</a>窗口按 <a href="/LLMTrain/05-速查表/术语速查#term-token" class="wiki-term" data-wiki-title="token" data-wiki-summary="文本经过分词规则得到的离散单元，随后会映射成整数 ID。" data-wiki-misconception="token 必然等于一个字或一个完整单词。">token</a> 数计算，不按字数计算。</p><h2 id="embedding-把-id-变成可计算的向量" tabindex="-1">Embedding 把 ID 变成可计算的向量 <a class="header-anchor" href="#embedding-把-id-变成可计算的向量" aria-label="Permalink to &quot;Embedding 把 ID 变成可计算的向量&quot;">​</a></h2><p>ID 只是索引。<a href="/LLMTrain/05-速查表/术语速查#term-embedding" class="wiki-term" data-wiki-title="embedding" data-wiki-summary="把离散 ID 映射为连续向量的可训练表示。" data-wiki-misconception="embedding 是人工指定的固定语义坐标。">Embedding</a> 表可以想成一张表，每个 <a href="/LLMTrain/05-速查表/术语速查#term-token" class="wiki-term" data-wiki-title="token" data-wiki-summary="文本经过分词规则得到的离散单元，随后会映射成整数 ID。" data-wiki-misconception="token 必然等于一个字或一个完整单词。">token</a> 对应一排会被训练的数字：</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>ID 0 -&gt; [ 0.2, -0.1,  0.7]</span></span>
<span class="line"><span>ID 1 -&gt; [-0.3,  0.8,  0.1]</span></span>
<span class="line"><span>ID 4 -&gt; [ 0.6,  0.4, -0.2]</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br></div></div><p>开始训练时这些数通常没有我们想要的语义。训练不断调整它们，使模型更善于完成预测目标。相近含义是否靠近，要看训练和度量，不能只凭一张二维投影图断言。</p><h2 id="顺序从哪里来" tabindex="-1">顺序从哪里来 <a class="header-anchor" href="#顺序从哪里来" aria-label="Permalink to &quot;顺序从哪里来&quot;">​</a></h2><p>单纯把 <a href="/LLMTrain/05-速查表/术语速查#term-token" class="wiki-term" data-wiki-title="token" data-wiki-summary="文本经过分词规则得到的离散单元，随后会映射成整数 ID。" data-wiki-misconception="token 必然等于一个字或一个完整单词。">token</a> 放进<a href="/LLMTrain/05-速查表/术语速查#term-attention" class="wiki-term" data-wiki-title="attention" data-wiki-summary="根据 Query 与 Key 的匹配权重，对 Value 做加权汇总。" data-wiki-misconception="注意力权重就是完整、可靠的人类可读解释。">注意力</a>计算，不足以区分顺序。因此模型需要位置信息。原始 <a href="/LLMTrain/05-速查表/术语速查#term-transformer" class="wiki-term" data-wiki-title="Transformer" data-wiki-summary="由注意力、MLP、残差连接和归一化等模块组成的一类神经网络架构。" data-wiki-misconception="所有大模型都只能采用同一种 Transformer 结构。">Transformer</a> 使用正弦位置编码；许多现代 Decoder 模型使用 RoPE 等方案。具体方案不同，但共同目标是让模型处理先后和距离。</p><h2 id="一个重要边界" tabindex="-1">一个重要边界 <a class="header-anchor" href="#一个重要边界" aria-label="Permalink to &quot;一个重要边界&quot;">​</a></h2><p><a href="/LLMTrain/05-速查表/术语速查#term-tokenizer" class="wiki-term" data-wiki-title="tokenizer" data-wiki-summary="负责把文本切成 token，并在 token 与整数 ID 之间转换的规则和词表。" data-wiki-misconception="tokenizer 是模型自己临时决定的切词方式。">Tokenizer</a> 决定了模型能看到的最小符号和序列长度成本。换 <a href="/LLMTrain/05-速查表/术语速查#term-tokenizer" class="wiki-term" data-wiki-title="tokenizer" data-wiki-summary="负责把文本切成 token，并在 token 与整数 ID 之间转换的规则和词表。" data-wiki-misconception="tokenizer 是模型自己临时决定的切词方式。">tokenizer</a> 通常会改变<a href="/LLMTrain/05-速查表/术语速查#term-vocab" class="wiki-term" data-wiki-title="vocab" data-wiki-summary="tokenizer 可以表示的 token 集合；输出层通常也对这组 token 给出分数。" data-wiki-misconception="词表包含了模型掌握的全部知识。">词表</a>大小、<a href="/LLMTrain/05-速查表/术语速查#term-embedding" class="wiki-term" data-wiki-title="embedding" data-wiki-summary="把离散 ID 映射为连续向量的可训练表示。" data-wiki-misconception="embedding 是人工指定的固定语义坐标。">Embedding</a> 和 <a href="/LLMTrain/05-速查表/术语速查#term-token" class="wiki-term" data-wiki-title="token" data-wiki-summary="文本经过分词规则得到的离散单元，随后会映射成整数 ID。" data-wiki-misconception="token 必然等于一个字或一个完整单词。">token</a> ID，不能把任意 <a href="/LLMTrain/05-速查表/术语速查#term-tokenizer" class="wiki-term" data-wiki-title="tokenizer" data-wiki-summary="负责把文本切成 token，并在 token 与整数 ID 之间转换的规则和词表。" data-wiki-misconception="tokenizer 是模型自己临时决定的切词方式。">tokenizer</a> 直接替换进已有模型而保持含义不变。</p><h2 id="动手任务" tabindex="-1">动手任务 <a class="header-anchor" href="#动手任务" aria-label="Permalink to &quot;动手任务&quot;">​</a></h2><p>给“机器学习”设计两种切分：</p><ul><li>字符级：<code>机 / 器 / 学 / 习</code></li><li>子词级：例如 <code>机器 / 学习</code></li></ul><p>比较<a href="/LLMTrain/05-速查表/术语速查#term-vocab" class="wiki-term" data-wiki-title="vocab" data-wiki-summary="tokenizer 可以表示的 token 集合；输出层通常也对这组 token 给出分数。" data-wiki-misconception="词表包含了模型掌握的全部知识。">词表</a>大小、序列长度和遇到生词时的表现。不存在对所有语言和任务都最优的唯一切法。</p><h2 id="今日验收" tabindex="-1">今日验收 <a class="header-anchor" href="#今日验收" aria-label="Permalink to &quot;今日验收&quot;">​</a></h2><ol><li><a href="/LLMTrain/05-速查表/术语速查#term-token" class="wiki-term" data-wiki-title="token" data-wiki-summary="文本经过分词规则得到的离散单元，随后会映射成整数 ID。" data-wiki-misconception="token 必然等于一个字或一个完整单词。">token</a> ID 为什么不能直接做乘除来表达语义？</li><li>字数为什么不等于 <a href="/LLMTrain/05-速查表/术语速查#term-token" class="wiki-term" data-wiki-title="token" data-wiki-summary="文本经过分词规则得到的离散单元，随后会映射成整数 ID。" data-wiki-misconception="token 必然等于一个字或一个完整单词。">token</a> 数？</li><li><a href="/LLMTrain/05-速查表/术语速查#term-embedding" class="wiki-term" data-wiki-title="embedding" data-wiki-summary="把离散 ID 映射为连续向量的可训练表示。" data-wiki-misconception="embedding 是人工指定的固定语义坐标。">Embedding</a> 在训练前后有什么变化？</li><li>为什么已有模型不能随意更换 <a href="/LLMTrain/05-速查表/术语速查#term-tokenizer" class="wiki-term" data-wiki-title="tokenizer" data-wiki-summary="负责把文本切成 token，并在 token 与整数 ID 之间转换的规则和词表。" data-wiki-misconception="tokenizer 是模型自己临时决定的切词方式。">tokenizer</a>？</li></ol><p>下一课：<a href="./D03-够用就好的数学基础">D03：够用就好的数学基础</a></p>`,23)])])}const h=i(r,[["render",o]]);export{w as __pageData,h as default};
